import { HistogramThresholdConfig } from '../../histogram/types/histogram.js';
import { TimeseriesChartThresholdConfig } from '../../timeseries/types/timeseries-config.js';
import { ThresholdMarker } from '../components/threshold-bar/ThresholdBar.js';
import { ThresholdPosition } from '../types/thresholds.js';
import {
  isStaticRange,
  isStatic,
  isDynamicRange,
  isDynamic,
  isDynamicNumeric,
  isDynamicNumericRange,
} from '../types/type-guards.js';
import { WithId } from '../types/with-id.js';

export const transformThresholdsToMarkers = (
  thresholds: WithId<
    TimeseriesChartThresholdConfig | HistogramThresholdConfig
  >[],
  position: ThresholdPosition,
) =>
  thresholds.map(({ data, color, id, label }): ThresholdMarker => {
    if (isStatic(data)) {
      return {
        id,
        color,
        y0: data.value,
        y1: data.value,
        label,
      };
    } else if (isStaticRange(data)) {
      return {
        id,
        color,
        y0: data.min,
        y1: data.max,
        label,
      };
    } else if (isDynamic(data) || isDynamicNumeric(data)) {
      const dataValue =
        position === 'left'
          ? data[0].value
          : data[2] && data[2].value && data[2].value;

      return {
        id,
        color,
        y0: dataValue,
        y1: dataValue,
        label,
      };
    } else if (isDynamicRange(data) || isDynamicNumericRange(data)) {
      const [dataY0] = data;
      // TODO ADES-3767: Fallback to data[0] because on the first run not all the thresold are passed to this component.
      const dataY1 = data[2] ?? data[0];

      const maxValue = position === 'left' ? dataY0.max : dataY1.max;
      const minValue = position === 'left' ? dataY0.min : dataY1.min;

      return {
        id,
        color,
        y0: minValue,
        y1: maxValue,
        label,
      };
    }

    return {
      id,
      color,
      y0: 0,
      y1: 0,
      label,
    };
  });
